#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, M, A;
    cin >> N >> K >> M >> A;

    vector<int> c(N + 1);
    for (int i = 0; i < A; ++i) {
        int x;
        cin >> x;
        ++c[x];
    }

    int l = M - A;

    for (int i = 1; i <= N; ++i) {
        vector<int> v;
        v.reserve(N - 1);

        for (int j = 1; j <= N; ++j) {
            if (i != j) v.push_back(c[j]);
        }

        sort(v.rbegin(), v.rend());

        int cc = 0;
        for (int x : v) {
            if (x >= c[i] + l) ++cc;
        }

        if (cc >= K) {
            cout << 3 << ' ';
            continue;
        }

        long long need = 0;
        if (K > static_cast<int>(v.size())) {
            need = static_cast<long long>(l) + 1;
        } else {
            for (int j = 0; j < K; ++j) {
                if (v[j] <= c[i]) {
                    need += c[i] + 1 - v[j];
                }
            }
        }

        if (need > l && c[i] > 0) cout << 1 << ' ';
        else cout << 2 << ' ';
    }

    return 0;
}

